mapper.select:
SELECT c.* FROM campus c INNER JOIN city ci ON ci.id = c.city_id AND ci.status = 1 WHERE c.status = 1
AND ( c.name LIKE CONCAT('%', #{keyword}, '%') OR c.short_name LIKE CONCAT('%', #{keyword}, '%') OR c.address LIKE CONCAT('%', #{keyword}, '%') )
AND ci.id = #{cityId}
ORDER BY c.sort_order ASC, c.id ASC LIMIT #{limit}
